def compute(vars):
    values = [
        vars["v1"],
        vars["v2"],
        vars["v3"],
        vars["v4"],
        vars["v5"],
        vars["v6"],
        vars["v7"],
    ]
    count_exceeding_threshold = sum(1 for value in values if value > 500000)

    return {
        "value": count_exceeding_threshold,
        "trace": {
            "threshold": 500000,
            "values": values,
            "count_exceeding_threshold": count_exceeding_threshold,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "count",
            },
        },
    }
